CREATE COLUMN TABLE "TEST_AP"."OITT" ("Code" NVARCHAR(50) NOT NULL , "TreeType" NVARCHAR(1) DEFAULT 'P', "PriceList" SMALLINT CS_INT DEFAULT 0, "Qauntity" DECIMAL(21,6) CS_FIXED, "CreateDate" LONGDATE CS_LONGDATE, "UpdateDate" LONGDATE CS_LONGDATE, "Transfered" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "SCNCounter" SMALLINT CS_INT, "DispCurr" NVARCHAR(3), "ToWH" NVARCHAR(8), "Object" NVARCHAR(20) DEFAULT '66', "LogInstac" INTEGER CS_INT, "UserSign2" INTEGER CS_INT, "OcrCode" NVARCHAR(8), "HideComp" NVARCHAR(1) DEFAULT 'N', "OcrCode2" NVARCHAR(8), "OcrCode3" NVARCHAR(8), "OcrCode4" NVARCHAR(8), "OcrCode5" NVARCHAR(8), "UpdateTime" INTEGER CS_INT, "Project" NVARCHAR(20), "PlAvgSize" DECIMAL(21,6) CS_FIXED DEFAULT 1, "Name" NVARCHAR(100), "CreateTS" INTEGER CS_INT, "UpdateTS" INTEGER CS_INT, "U_OriginType" NVARCHAR(20), "U_OriginCode" INTEGER CS_INT, "U_OriginLine" INTEGER CS_INT, "U_Inactive" NVARCHAR(10) DEFAULT 'N', PRIMARY KEY ("Code")) UNLOAD PRIORITY 0  AUTO MERGE ;
